probe.setup:
window.ARC = window.ARC || {};
ARC.state = window.SEED;
ARC.esc = function (s) { return String(s == null ? '' : s); };
ARC.uid = function (p) { return p + '-' + Math.random().toString(36).slice(2, 8); };
ARC.save = function () {};
ARC.render = function () {};
ARC.navigate = function () {};
ARC.notify = function () {};
ARC.openDialog = function () {};
ARC.closeDialog = function () {};
ARC.openPopover = function () {};
ARC.closePopover = function () {};
ARC.combobox = function () { return ''; };
ARC.route = function () { return { name: 'repo', params: [] }; };
ARC.currentUser = function () { var s = window.SEED.session; return (window.SEED.users || []).filter(function (u) { return u.id === s; })[0] || null; };

probe.precondition:
assert.strictEqual(ARC.state.session, null);
assert.ok(ARC.state.repositories.some(function (r) { return r.id === 'r1'; }));
assert.ok(ARC.state.protectionRules.some(function (r) { return r.repoId === 'r1' && r.branch === 'main' && r.requireApproval && r.requireCheck; }));

probe.check:
var repo = ARC.state.repositories.filter(function (r) { return r.id === 'r1'; })[0];
var open = ARC.state.pulls.filter(function (p) { return p.repoId === 'r1' && p.state === 'Open'; });
var eligible = open.filter(function (p) { return mergeBlocked(p, repo) === null; });
var blocked = open.filter(function (p) { return mergeBlocked(p, repo) === 'Review required by branch protection'; });
assert.ok(eligible.length >= 1, 'seed must provide the mergeable Open PR for the success scenario');
assert.ok(blocked.length >= 1, 'seed must provide a separate Open PR blocked with Review required by branch protection for the refusal scenario');
